"""Report and package CT-atlas reprojection outputs without changing analyses."""
from pathlib import Path
import hashlib,html,json,zipfile
import h5py,numpy as np,pandas as pd
from ct_velocity_reproject import OUT,OLD,ATLAS,dump,read_csr,log
HERE=Path(__file__).resolve().parent
STYLE='<style>body{font:16px system-ui,sans-serif;max-width:1250px;margin:30px auto;padding:0 20px;line-height:1.55;color:#253445}img{max-width:100%}table{border-collapse:collapse;font-size:13px}th,td{padding:8px;border:1px solid #ddd}pre{white-space:pre-wrap;background:#f1f5f8;padding:15px}.finding{background:#edf5f7;padding:18px;border-left:4px solid #287788}</style>'

def diagnostics():
 rows=[]
 for name in ['reused','updated']:
  with h5py.File(OUT/f'{name}_projection.h5') as f:
   y=f['umap2d'][:];n=len(y);span=np.linalg.norm(np.ptp(y,axis=0))
   for t in range(5):
    g=f[f'projection/{t}'];P=read_csr(g['probabilities']);meanlen=np.zeros(n)
    for start in range(0,n,8192):
     stop=min(n,start+8192);a,b=P.indptr[start],P.indptr[stop];r=np.repeat(np.arange(stop-start),np.diff(P.indptr[start:stop+1]));j=P.indices[a:b];dist=np.linalg.norm(y[j].astype(float)-y[start+r].astype(float),axis=1);meanlen[start:stop]=np.bincount(r,weights=P.data[a:b]*dist,minlength=stop-start)
    valid=g['projection_valid/umap2d'][:];active=g['active'][:];row=dict(method=name,interval=t,median_weighted_edge_length=float(np.median(meanlen[active])),median_edge_length_fraction_atlas_diagonal=float(np.median(meanlen[active])/span),projected_2d=int(valid.sum()))
    if name=='updated':
     v=g['vectors/umap2d'][:];b=g['baseline_vectors/umap2d'][:];norm=np.linalg.norm(b,axis=1);den=np.linalg.norm(v,axis=1)*norm;cs=np.divide(np.sum(v*b,axis=1),den,out=np.zeros(n),where=den>0);mask=valid&(norm>.05);row.update(geometry_comparable=int(mask.sum()),median_baseline_direction_cosine=float(np.median(cs[mask])),fraction_baseline_cosine_gt08=float((cs[mask]>.8).mean()))
    rows.append(row)
 pd.DataFrame(rows).to_csv(OUT/'edge_locality_and_geometry.csv',index=False)


def report():
 cov=pd.read_csv(OUT/'projection_coverage.csv');agree=pd.read_csv(OUT/'projection_method_agreement.csv');geom=pd.read_csv(OUT/'edge_locality_and_geometry.csv');manifest=json.loads((OUT/'figure_manifest.json').read_text());graph=json.loads((OUT/'new_graph_manifest.json').read_text());view=json.loads((OUT/'viewer_payload_validation.json').read_text()) if (OUT/'viewer_payload_validation.json').exists() else {}
 selected=cov[(cov.method=='updated')&(cov.embedding=='umap2d')].copy();selected['Interval (hpf)']=selected.start_hpf.astype(str)+'–'+selected.end_hpf.astype(str);table=selected[['Interval (hpf)','source_changing','projected','positive_net','negative_net']];table.columns=['Interval (hpf)','Supported-changing sources','Projected in 2D','Positive mean rate','Negative mean rate']
 comp=agree.query('embedding=="umap2d"')[['interval','comparable','median_direction_cosine','fraction_reversed']].copy();comp['fraction_reversed']*=100;comp.columns=['Interval index (0–4)','Both methods project','Median direction cosine','Directions differ >90° (%)']
 bg=geom.query('method=="updated"').median_baseline_direction_cosine; geometry_text=f'Median direction cosine with the unfiltered graph tendency is {bg.min():.3f}–{bg.max():.3f} across intervals. This strong alignment means that neighborhood geometry contributes substantially to the displayed directions; the diagnostic alone does not establish their biological origin.'
 newreach=geom.query('method=="updated"').median_weighted_edge_length.mean();oldreach=geom.query('method=="reused"').median_weighted_edge_length.mean()
 body='''<h1>Chromatin velocities on the new celltype peak UMAP</h1><div class="finding"><strong>The existing temporal velocities have been reprojected in both 2D and 3D.</strong> The measured accessibility and six-stage fits did not change, so the previous CPM/hour rates were reused. The primary view updates candidate neighbors in the new atlas’s high-dimensional log-CPM PCA space. A separate control preserves the previous directed weights and changes only coordinates.</div><p><a href="ct_velocity_explorer.html">Open offline 2D/3D velocity explorer</a> · <a href="projection_coverage.csv">Projection coverage</a> · <a href="projection_method_agreement.csv">Method agreement</a> · <a href="edge_locality_and_geometry.csv">Edge locality and geometry diagnostics</a></p><h2>Primary 2D arrows</h2><img src="01_ct_umap_velocity_arrows.png"><p>Each point is a fixed genomic peak. The UMAP summarizes its full course across 190 celltype × stage features; each interval’s velocity is a 21-celltype vector. Arrows point toward neighboring peaks whose stage-specific profiles align with the source peak’s fitted change. This is a local correspondence on the whole-course atlas, not literal motion of a genomic peak or an exact derivative through a 190-feature moving-state embedding.</p>'''+table.to_html(index=False)+'''<p>Red/blue encode the signed mean fitted accessibility rate across valid celltypes. Arrow direction is a separate quantity: pointing inward does not necessarily mean closing, and pointing outward does not necessarily mean opening. Static arrows select the highest-coherence eligible peak per spatial bin, then favor spatial coverage. They are coherent display examples, not an unbiased sample of all directions. Equal-length arrows make directions visible; their lengths are not biological speeds. No root, entropy, tau or required radial direction orients an edge.</p><h2>What was reused and what was recomputed</h2><ul><li><strong>Reused:</strong> fitted six-stage linear CPM curves, actual time gaps (2, 2, 2, 3, 5 hours), conditional errors/support gates, fixed 21-celltype panel, and the new frozen 2D/3D atlas coordinates.</li><li><strong>Recomputed:</strong> 30 high-dimensional PCA neighbors per peak, graph weights, cosine transition probabilities, embedding direction vectors, coherence and display masks for each interval.</li><li><strong>Coordinate-only control:</strong> previous transition probabilities remain exactly unchanged; only unit directions to their targets and display masks are recalculated on the new map.</li></ul><p>The full 640,830-peak candidate graph uses Euclidean distance in the 50-PC log1p(CPM) representation. PyNNDescent achieved '''+f'{100*graph["audit_mean_recall"]:.3f}%'+''' mean recall of the exact 30 neighbors across 128 audited queries against all peaks. Directed weights are exp(−distance / the row’s 30th-neighbor distance). This is a newly built candidate graph, not the original UMAP training graph. Biological cosine alignment compares linear CPM states with linear CPM/hour rates, preserving the hybrid geometry/rate distinction used in the preceding validation.</p><h2>Separate map changes from neighborhood changes</h2><img src="02_reprojection_controls.png"><p>The top row reconstructs the previous plot. The middle row changes only coordinates. The bottom row also changes candidate neighbors and their weights. All three have identical temporal rates and source gates. The coordinate-only control can retain edges that are no longer local on the new map.</p>'''+comp.to_html(index=False,float_format=lambda x:f'{x:.3f}')+f'''<p>Across the five intervals, the mean of interval-median probability-weighted 2D edge lengths is {oldreach:.4g} for previous weights and {newreach:.4g} for updated neighbors (same new-map units). This measures projection locality, not biological accuracy. {geometry_text}</p>'''+'''<h2>Stream-style display</h2><img src="03_ct_umap_velocity_streams.png"><p>These curves interpolate the same primary per-peak directions. Finite-radius support, local direction agreement and path clipping prevent extrapolation through unsupported grid regions. Streamline width and length are display properties; smoothing can still conceal opposing directions or join programs that overlap in 2D. The saved grid/path files and audits make these display choices reviewable.</p><h2>3D directions</h2><img src="04_ct_umap_velocity_3d.png"><p>The static 3D panels display 60,000 background peaks and up to 150 arrows per interval. All 640,830 peaks were evaluated. The offline explorer provides rotation, interval/method switches, color choices, and display-density/length controls. Its subset is for rendering only; full arrays remain on disk.</p><h2>Opening/closing and magnitude remain unchanged</h2><img src="05_signed_rate_and_magnitude.png"><p>The signed mean and RMS rate values are identical between the two reprojections. Net rates can cancel opposing changes across celltypes. Missing/undefined summaries remain missing rather than becoming zero.</p><h2>Interpretation</h2><p>This answers the visualization question: the existing fitted chromatin changes can be shown on the new celltype-based atlas, using a matched high-dimensional neighborhood definition. The five intervals should remain separate because opening and closing can reverse through development.</p><p>'''+geometry_text+'''</p><p>The preceding independent-cell/count-noise analyses still apply. A smooth local field does not establish a global root-to-branch stream; the present change is a reprojection, not new independent biological validation. Source gates describe conditional fit/count support, not biological confidence. CPM measures relative accessibility, and timepoint/batch and subtype composition remain potential contributors to the trajectories.</p><h2>Saved outputs and checks</h2><ul><li><code>updated_projection.h5</code>: ordered peak IDs, coordinates, new sparse graph, all five transition matrices and projection arrays.</li><li><code>reused_projection.h5</code>: coordinate-only control with unchanged previous transition weights.</li><li><code>chromatin_velocity_ct_umap.h5ad</code>: AnnData with original high-dimensional state/rate layers, new coordinates and projected velocities.</li><li><code>new_graph_manifest.json</code>, <code>new_graph_projection_validation.json</code>, <code>reused_validation.json</code>, export and viewer checks: provenance and numerical validation.</li><li><code>stream_display/</code>: actual displayed grid fields and clipped paths; <code>plot_arrow_indices.npz</code>: selected static arrows.</li></ul><p>Source fits and atlas objects remain unchanged. Reconstructing the old arrows recovered their values within floating-point precision and their masks exactly; the newly drawn arrows use newly computed directions.</p><pre>python ct_velocity_reproject.py reuse
python ct_velocity_reproject_core.py --stage all
python ct_velocity_reproject_figures.py
python ct_velocity_reproject_viewer.py
python ct_velocity_reproject_export.py
python ct_velocity_reproject_report.py</pre>'''
 (OUT/'report.html').write_text('<!doctype html><meta charset="utf-8"><title>CT UMAP chromatin velocity</title>'+STYLE+body)
 return selected,agree

if __name__=='__main__':diagnostics();report()
